import Foundation

/// Fonts that draw symbols under the names of letters, with no ToUnicode map to say what they are.
///
/// Elsevier's and Springer's typesetters (Advent) set bullets, ©, Greek and math with "Pi" and symbol
/// fonts whose glyphs are named like letters: Cell's Highlights draw their bullets as "d" in
/// AdvPSMPi6 and "© 2024 The Author(s)" as "ª" in AdvPSSym, so the text read "d ISS elucidates…" and
/// "ª 2024". Each table gives the glyph names of one family (as the encoding's Differences name them,
/// or as the base encoding names the code) and what the glyph shows. The tables come from the glyphs
/// themselves, drawn from the fonts embedded in the evaluation's PDFs and the test library (Symbol's
/// and TeX's OMS layout where a font follows one), not from guesses; a name a table does not have is
/// left as it is. Advent's ToUnicode maps, where there are any, often just restate the names (0xAA →
/// U+00AA): such a map does not count (see PDFContentScanner.fontInfo).
enum SymbolFonts {
    struct Family {
        /// font names (after the subset prefix) that end with one of these
        let keys: [String]
        /// glyph name → text
        let names: [String: String]
        /// code → text for a font without Differences there, by base encoding
        let winAnsi: [Int: String], macRoman: [Int: String], standard: [Int: String]
        /// glyph name → the character the name stands for elsewhere ("ordfeminine" ª): a ToUnicode map
        /// that gives a glyph only this says no more than the name
        let plain: [String: String]
        /// what PDFKit reads for a glyph → what it is, for a font with its own encoding (no Encoding
        /// entry), whose codes say nothing of the names: TeX CM Maths Symbols' "ð1Þ" → "(1)"
        let byRead: [String: String]
    }

    /// The family of a font, by its name without the subset prefix ("HBKIKE+AdvPSMPi6" → AdvPSMPi6;
    /// Springer's "XcyghdAdvPi3" ends with AdvPi3; "Wingdings-Regular" is Wingdings).
    static func family(_ baseFont: String) -> Family? {
        let name = baseFont.contains("+") ? String(baseFont.split(separator: "+", maxSplits: 1).last ?? "") : baseFont
        for f in families {
            for k in f.keys {
                if name.hasSuffix(k) { return f }
                if name.hasPrefix(k), let last = k.last, !last.isNumber {
                    let rest = name.dropFirst(k.count)
                    if rest == "-Regular" || rest.allSatisfy(\.isNumber) { return f }
                }
            }
        }
        return nil
    }

